try {
  // 1. Read input safely from the AI Agent
  let rawInput = $fromAI('url', 'The full web URL to scrape') || '';

  // 2. Extract valid HTTP/HTTPS URL
  const urlMatch = rawInput.match(/https?:\/\/[^\s"'<>]+/i);
  if (!urlMatch) {
    return `Error: No valid URL found in input: "${rawInput}"`;
  }

  let cleanUrl = urlMatch[0].replace(/[.,;)]+$/, '');

  // 3. Perform native HTTP fetch
  const response = await fetch(cleanUrl, {
    method: 'GET',
    redirect: 'follow',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36'
    }
  });

  if (!response.ok) {
    return `HTTP Error ${response.status}: Unable to fetch ${cleanUrl}`;
  }

  const text = await response.text();

  // 4. Strip scripts, styles, and HTML tags
  const cleanText = text
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return cleanText.slice(0, 4000) || "Page fetched, but no text content found.";

} catch (error) {
  return `Failed to scrape webpage: ${error.message}`;
}
